#include <unistd.h>
#include <string.h>

#define FILE_NAME "test_mmap.txt"
#define FILE_SIZE 4096 // One page

int main() {
    int fd;
    struct stat sb;
    void *addr; // Pointer to the mapped memory

    // Open/Create file
    fd = open(FILE_NAME, O_RDWR | O_CREAT, 0644);
    if (fd == -1) { perror("open"); return 1; }

    // Ensure file has size
    if (ftruncate(fd, FILE_SIZE) == -1) { perror("ftruncate"); close(fd); return 1; }

    // Get file size (for mmap length)
    if (fstat(fd, &sb) == -1) { perror("fstat"); close(fd); return 1; }

    // Call mmap
    addr = mmap(NULL, sb.st_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (addr == MAP_FAILED) { perror("mmap"); close(fd); return 1; }

    printf("File mapped at address: %p\n", addr);

