    const char *message = "Hello, Memory-Mapped File!";
    memcpy(addr, message, strlen(message));
    printf("Wrote '%s' to mapped memory.\n", (char*)addr);

    // Clean up
    munmap(addr, sb.st_size);
    close(fd);

    return 0;
}
```

