#include <sys/syscall.h> // For SYS_fork
#include <stdio.h>

// A simplified wrapper to demonstrate the syscall directly
pid_t my_fork_syscall() {
    // On x86-64, system call number goes into RAX
    // Arguments go into RDI, RSI, RDX, R10, R8, R9
    // fork() takes no arguments.
    return syscall(SYS_fork);
}

int main() {
    pid_t pid = my_fork_syscall(); // The call we're interested in
    if (pid == 0) {
        printf("Child process: PID = %d\n", getpid());
    } else if (pid > 0) {
        printf("Parent process: PID = %d, Child PID = %d\n", getpid(), pid);
    } else {
        perror("fork failed");
    }
    return 0;
}
```

