    movq    %rsp, %rbp       ; Set new base pointer

    movl    $2, %eax         ; 1. Load system call number into EAX (lower 32-bits of RAX)
                             ;    SYS_fork is 2 on x86-64 Linux.
                             ;    No arguments for fork, so RDI, RSI, RDX etc. are not set.

