auto capturing_lambda_compare = [threshold](const void* a, const void* b) -> int {
    int val1 = *static_cast<const int*>(a);
    int val2 = *static_cast<const int*>(b);
    if (val1 < threshold && val2 < threshold) {
        return val1 - val2;
    } else if (val1 >= threshold && val2 >= threshold) {
