; Assume d_obj is at -24(%rbp) and b_obj is at -16(%rbp) on the stack

    ; d_obj constructor call (Derived::Derived(int, int))
    ; movl    $10, -24(%rbp)  ; d_obj.base_data = 10
    ; movl    $20, -20(%rbp)  ; d_obj.derived_data = 20

    ; Base b_obj = d_obj;  <-- Slicing happens here
    movl    -24(%rbp), %eax ; Load d_obj.base_data (10) into EAX
    movl    %eax, -16(%rbp) ; Store EAX into b_obj.base_data

    ; b_obj.print(); call
    ; ...
```

**Explanation of Assembly:**

1.  `movl -24(%rbp), %eax`: The value of `d_obj.base_data` (which is 10, located at `rbp-24`) is loaded into the `EAX` register. `EAX` is the lower 32-bit part of `RAX`.
2.  `movl %eax, -16(%rbp)`: The value from `EAX` (10) is then stored into `b_obj.base_data` (located at `rbp-16`).

Notice that only the `base_data` member is copied. The `derived_data` member of `d_obj` (at `rbp-20`) is completely ignored and not copied to `b_obj`, as `b_obj` does not have a `derived_data` member. This is the essence of slicing.

---

### Polymorphism with Virtual Functions: Dynamic Dispatch

To avoid slicing and enable dynamic behavior, we use polymorphism with virtual functions. Polymorphism allows us to call the correct version of a function at runtime, even if the function is called through a base class pointer or reference. This is crucial for flexible and extensible object-oriented design.

The `virtual` keyword in the base class function declaration is the key.

**C++ Example:**

```c++
#include <iostream>

class Base {
public:
    int base_data; // 4 bytes
    Base(int bd = 0) : base_data(bd) {}
    virtual void myFunction() { std::cout << "Base::myFunction(), base_data: " << base_data << "\n"; }
    virtual ~Base() {} // Virtual destructor is crucial for proper cleanup
};

class Derived : public Base {
public:
    int derived_data; // 4 bytes
    Derived(int bd = 0, int dd = 0) : Base(bd), derived_data(dd) {}
    void myFunction() override { std::cout << "Derived::myFunction(), derived_data: " << derived_data << ", base_data: " << base_data << "\n"; }
    ~Derived() override {}
};

void call_my_function(Base* obj_ptr) {
    obj_ptr->myFunction(); // Virtual call
}

int main() {
    Derived d_obj(100, 200); // d_obj.base_data = 100, d_obj.derived_data = 200
    Base b_obj(50);          // b_obj.base_data = 50

    call_my_function(&d_obj); // Calls Derived::myFunction()
    call_my_function(&b_obj); // Calls Base::myFunction()

    return 0;
}
```

