template <typename T, typename = std::enable_if_t<!std::is_pointer<T>::value>>
void foo(T val) {
    std::cout << "general: " << val << "\n";
}

// Constrained for pointer types
template <typename T, typename = std::enable_if_t<std::is_pointer<T>::value>>
void foo(T ptr) {
    std::cout << "pointer: " << *ptr << "\n";
}

int main() {
    int x = 42;
    int* p = &x;
    foo(p); // This will now unambiguously call the pointer overload
    foo(x); // This will unambiguously call the general overload
    return 0;
}
```

