    // CRTP: Allows static polymorphism to call the derived class's operator[]
    const Derived& asDerived() const { return static_cast<const Derived&>(*this); }

    // This operator[] is called by the assignment operator of Vector.
    // It delegates to the specific expression's operator[] to get the element value.
    T operator[](size_t i) const { return asDerived()[i]; }
