    uint8_t  version;      // 1 byte
    uint8_t  flags;        // 1 byte
    uint16_t length;       // 2 bytes
    uint32_t sequence_num; // 4 bytes
    uint64_t timestamp;    // 8 bytes
    char     status_msg[8]; // 8 bytes
};

// Function to process a header (takes a pointer)
void process_header(struct PacketHeader *header_ptr) {
    printf("Processing Header:\n");
    printf("  Version: %u\n", header_ptr->version);
    printf("  Flags: %u\n", header_ptr->flags);
    printf("  Length: %u\n", header_ptr->length);
    printf("  Sequence Num: %u\n", header_ptr->sequence_num);
    printf("  Timestamp: %lu\n", header_ptr->timestamp);
    printf("  Status: %s\n", header_ptr->status_msg);
}

int main() {
    struct PacketHeader my_packet;

    // Print size and offsets (compile-time information)
    printf("Size of PacketHeader: %zu bytes\n", sizeof(struct PacketHeader));
    printf("Offset of version: %zu\n", offsetof(struct PacketHeader, version));
    printf("Offset of flags: %zu\n", offsetof(struct PacketHeader, flags));
    printf("Offset of length: %zu\n", offsetof(struct PacketHeader, length));
    printf("Offset of sequence_num: %zu\n", offsetof(struct PacketHeader, sequence_num));
    printf("Offset of timestamp: %zu\n", offsetof(struct PacketHeader, timestamp));
    printf("Offset of status_msg: %zu\n", offsetof(struct PacketHeader, status_msg));
    printf("-----------------------------------\n");

    // Initialize members
    my_packet.version = 4;
    my_packet.flags = 0x02;
    my_packet.length = 1500;
    my_packet.sequence_num = 12345;
    my_packet.timestamp = 0xDEADBEEFCAFELL;
    snprintf(my_packet.status_msg, sizeof(my_packet.status_msg), "OK");

    process_header(&my_packet);

    // Accessing members directly in main
