#include <unistd.h>     // For pid_t, ssize_t
#include <stdio.h>      // For printf, perror
#include <string.h>     // For strlen

// A wrapper function to directly call the system call
ssize_t my_process_vm_writev_wrapper(pid_t pid,
                                     const struct iovec *local_iov,
                                     unsigned long liovcnt,
                                     const struct iovec *remote_iov,
                                     unsigned long riovcnt,
                                     unsigned long flags) {
    // The syscall() function is a glibc wrapper that handles the
    // register setup and the 'syscall' instruction.
    return syscall(SYS_process_vm_writev,
                   pid,
                   local_iov,
                   liovcnt,
                   remote_iov,
                   riovcnt,
                   flags);
}

int main() {
    pid_t target_pid = 1234; // Example PID
    char local_buffer[] = "Hello from local process!";

    // Define local iovec structure
    struct iovec local_iov_arr[1];
    local_iov_arr[0].iov_base = local_buffer;
    local_iov_arr[0].iov_len = strlen(local_buffer);

    // Define remote iovec structure (target address in remote process)
    struct iovec remote_iov_arr[1];
    // In a real scenario, this would be a valid address in 'target_pid'
    remote_iov_arr[0].iov_base = (void*)0xDEADBEEF0000; // Dummy remote address
    remote_iov_arr[0].iov_len = strlen(local_buffer);

    unsigned long liov_count = 1;
    unsigned long riov_count = 1;
    unsigned long call_flags = 0; // Must be 0 for process_vm_writev

