#include <stdio.h>
#include <stdlib.h> // For malloc, free

// Global variable: Initialized data segment (.data)
int global_initialized_var = 123;

// Uninitialized global variable: BSS segment (.bss)
int global_uninitialized_var; // Automatically initialized to 0 by OS/loader

void demonstrate_pointers() {
    // Local variable: Stack
    int stack_var = 456;

    // Dynamically allocated memory: Heap
    int *heap_ptr = (int *)malloc(sizeof(int));
    if (heap_ptr == NULL) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }
    *heap_ptr = 789;

    printf("--- Memory Addresses (Virtual) ---\n");
    printf("Address of 'demonstrate_pointers' function (Text segment): %p\n", (void *)demonstrate_pointers);
    printf("Address of 'global_initialized_var' (Data segment):       %p\n", (void *)&global_initialized_var);
    printf("Address of 'global_uninitialized_var' (BSS segment):     %p\n", (void *)&global_uninitialized_var);
    printf("Address of 'stack_var' (Stack segment):                  %p\n", (void *)&stack_var);
    printf("Address pointed to by 'heap_ptr' (Heap segment):         %p\n", (void *)heap_ptr);
    printf("Address of 'heap_ptr' variable itself (Stack segment):   %p\n", (void *)&heap_ptr); // heap_ptr is a local variable

    printf("\n--- Values ---\n");
    printf("Value of 'global_initialized_var': %d\n", global_initialized_var);
    printf("Value of 'global_uninitialized_var': %d (default 0)\n", global_uninitialized_var);
    printf("Value of 'stack_var': %d\n", stack_var);
    printf("Value pointed to by 'heap_ptr': %d\n", *heap_ptr);

    free(heap_ptr);
}

int main() {
    demonstrate_pointers();
    return 0;
}
```

