    subq    $16, %rsp           # Allocate stack space for obj reference
    movq    %rdi, -8(%rbp)      # Store 'obj' reference (passed in RDI) on stack

    # Accessing obj.private_data_A
    movq    -8(%rbp), %rax      # Load the address of 'obj' into RAX
    movl    (%rax), %edx        # Load the integer at offset 0 from RAX into EDX
