struct old_utsname {
    char sysname[9];    // Operating system name
    char nodename[9];   // Name of this node
    char release[9];    // OS release
    char version[9];    // OS version
    char machine[9];    // Hardware identifier
    // Note: oldolduname typically does not include 'domainname'
    // or other extended fields found in modern utsname.
};
```

