// The data pointed to by 'data_ptr' cannot be modified via this pointer.
// This allows the compiler to assume the data is immutable through 'data_ptr'.
int process_const_data(const int *data_ptr) {
    // Attempting *data_ptr = 200; would be a compile-time error.
    // The compiler knows 'data_ptr' points to immutable data.
    return *data_ptr + GLOBAL_CONST_VALUE;
}

// Function 2: Takes a const pointer to int (int *const data_ptr)
// The pointer 'data_ptr' itself cannot be reassigned to point elsewhere.
// The data it points to *can* be modified.
