// Neither the pointer nor the data it points to can be modified via 'data_ptr'.
int read_const_data_via_const_ptr(const int *const data_ptr) {
    // *data_ptr = 300; would be a compile-time error.
    // data_ptr = NULL; would be a compile-time error.
    return *data_ptr;
}

// Function 4: Demonstrates a non-const pointer for comparison
void modify_value(int *value_ptr) {
    *value_ptr = 42;
}

int main() {
    int my_value = 10;
    int another_value = 20;

    // Scenario 1: pointer to const int
    const int *ptr_to_const = &my_value;
    printf("Processing const data: %d\n", process_const_data(ptr_to_const));
    // my_value is still 10, as process_const_data didn't modify it.

    // Scenario 2: const pointer to int
    int *const const_ptr_to_data = &another_value;
    printf("Modifying data via const pointer var: %d\n", modify_data_via_const_ptr_var(const_ptr_to_data));
