#include <string>

// 1. Base case for variadic template recursion (no arguments)
void print() {
    std::cout << "End of variadic print." << std::endl;
}

// 2. Specific non-variadic overload for a single int
void print(int x) {
    std::cout << "Specific overload for int: " << x << std::endl;
}

// 3. Specific non-variadic overload for a single double
void print(double d) {
    std::cout << "Specific overload for double: " << d << std::endl;
}

// 4. Variadic template: processes 'first' and recursively calls itself for 'rest'
template<typename T, typename... Args>
void print(T first, Args... rest) {
    std::cout << "Variadic print: " << first << ", ";
    print(rest...); // Recursive call
}

int main() {
    // Case A: Calls specific print(int)
    print(42);

    // Case B: Calls specific print(double)
    print(3.14);

    // Case C: Calls variadic print<const char*>(const char*)
    print("hello");

    // Case D: Calls variadic print<int, double, const char*>(int, double, const char*)
    print(1, 2.0, "world");

    // Case E: Calls base case print()
    print();

    return 0;
}
```

