    uint32_t value_32bit = 0x12345678; // A 32-bit integer
    unsigned char *byte_ptr_32bit = (unsigned char *)&value_32bit; // Pointer to the first byte

    printf("--- 32-bit Integer (uint32_t) ---\n");
    printf("Original value: 0x%08X\n", value_32bit);
    printf("Memory representation (Little-Endian on x86-64):\n");

    // Iterate through the bytes
    for (size_t i = 0; i < sizeof(value_32bit); ++i) {
        printf("  Byte at offset %zu: 0x%02X (address: %p)\n", i, byte_ptr_32bit[i], (void*)(byte_ptr_32bit + i));
    }

