    printf("Memory representation (Little-Endian on x86-64):\n");
    for (size_t i = 0; i < sizeof(value_64bit); ++i) {
        printf("  Byte at offset %zu: 0x%02X (address: %p)\n", i, byte_ptr_64bit[i], (void*)(byte_ptr_64bit + i));
