    float value_float = 123.456f;
    unsigned char *byte_ptr_float = (unsigned char *)&value_float;

    printf("\n--- Floating-Point (float) ---\n");
    printf("Original value: %f\n", value_float);
    printf("Memory representation (Little-Endian on x86-64):\n");
    // The exact hex representation of 123.456f is 0x42F6E979
    for (size_t i = 0; i < sizeof(value_float); ++i) {
        printf("  Byte at offset %zu: 0x%02X (address: %p)\n", i, byte_ptr_float[i], (void*)(byte_ptr_float + i));
